// Real archive collections are assets.equipment/textures/custom.
for (const g of [...fieldGroups, ...supplementalFields]) {
  g.paths = g.paths.map(p => p.replace('$assets.customAssets', '$assets.custom').replace('$assets.equipmentAssets', '$assets.equipment'));
}
// These values are also editable on site monitoring equipment; keep the owner path.
for (const name of ['EquipmentIdentity','CoordinateFrame','Enclosure','DoorSet']) {
  const g = [...fieldGroups,...supplementalFields].find(value=>value.name===name);
  g.paths.push(...g.paths.filter(p=>p.startsWith(EP[0])).map(p=>p.replace(EP[0],'siteObjects[]')));
}
// Layered terrain is the same data structure at a different JSON path.
for (const name of ['Terrain','TerrainDefaults','TerrainGradient','TerrainCellColor','TerrainRemovedArea']) {
  const g = fieldGroups.find(value=>value.name===name);
  g.paths.push(...g.paths.map(p=>p.replace('siteEnvironment.terrain','floorPlansById.{floorId}.terrain')));
}
fieldGroups.find(g=>g.name==='RoomDetailAsset').omit = ['objectUrl'];
supplementalFields.find(g=>g.name==='NativeArchive').fields = supplementalFields.find(g=>g.name==='NativeArchive').fields.filter(f=>f.path!=='encoding');
